from pathlib import Path
import json,hashlib,math
import numpy as np
from PIL import Image
P=Path(__file__).resolve().parent
def write(name,d):
 (P/name).write_text(json.dumps(d,indent=2)+'\n')
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def digest(d):return hashlib.sha256(json.dumps(d,sort_keys=True,separators=(',',':')).encode()).hexdigest()
audits={m:json.loads((P/(m+'-audit.json')).read_text()) for m in ['main','runtime']}
def alpha(path,t):
 im=Image.open(path).convert('RGBA');a=np.array(im)[:,:,3];yy,xx=np.where(a>=t);bottom=int(yy.max());xs=np.where(a[bottom]>=t)[0]
 return {'size':list(im.size),'bboxTopOriginExclusive':[int(xx.min()),int(yy.min()),int(xx.max()+1),int(yy.max()+1)],'visibleWidthPixels':int(xx.max()+1-xx.min()),'bottomRimPixelCenterTopOrigin':[(float(xs.min())+float(xs.max())+1)/2,bottom+.5],'bottomRowSpanExclusive':[int(xs.min()),int(xs.max()+1)]}
maps={}
