 a=audits[mode];src=P/(mode+'-source-food.png');canon=P.parent/json.loads((P.parent/'brief.json').read_text())['foodDependencies'][food]['artwork'];S=alpha(src,128);C=alpha(canon,128);W,H=S['size'];cw,ch=C['size'];uv=a['food']['uv'];v=a['food']['vertices'];uvx0=uv[0][0]*W;uvx1=uv[1][0]*W;uvy0=uv[0][1]*H
 # Use measured source quad/UV, one uniform physical scale, and actual opaque bottom rim pixel-center support.
 ksrc=(v[1][0]-v[0][0])/(uvx1-uvx0)
