 vertices=[[offset[0],offset[1],0],[offset[0]+cw*k,offset[1],0],[offset[0]+cw*k,offset[1]+ch*k,0],[offset[0],offset[1]+ch*k,0]]
 sens={}
 for t in [64,128,192]:
  st,ct=alpha(src,t),alpha(canon,t);sa=st['bottomRimPixelCenterTopOrigin'];ca=ct['bottomRimPixelCenterTopOrigin'];sp=[v[0][0]+(sa[0]-uvx0)*ksrc,v[0][1]+(H-sa[1]-uvy0)*ksrc];cp=[offset[0]+ca[0]*k,offset[1]+(ch-ca[1])*k]
  sens[str(t)]={'source':st,'canonical':ct,'sourceVisibleWidthWorld':st['visibleWidthPixels']*ksrc*1.25,'mappedCanonicalVisibleWidthWorld':ct['visibleWidthPixels']*k*1.25,'bottomRimDeltaWorld':[1.25*(cp[i]-sp[i]) for i in range(2)]}
 proof=[];ray=np.array([0,-math.cos(math.radians(35)),math.sin(math.radians(35))])
 for s in a['samples']:
  fm=np.array(s['food']['planeMatrix']);rm=np.array(s['food']['rootMatrix']);srcpoint=fm@np.array([srcAnchor[0],srcAnchor[1],0,1]);canpoint=fm@np.array([offset[0]+C['bottomRimPixelCenterTopOrigin'][0]*k,offset[1]+(ch-C['bottomRimPixelCenterTopOrigin'][1])*k,0,1]);center=fm@np.array([0,0,0,1]);delta=center[:3]-rm[:3,3]
  proof.append({'clip':s['clip'],'frame':s['frame'],'direction':s['direction'],'visible':s['food']['visible'],'supportWorld':srcpoint[:3].tolist(),'supportProjected':[192+256*srcpoint[0],496-256*(math.sin(math.radians(35))*srcpoint[1]+math.cos(math.radians(35))*srcpoint[2])],'mappingSupportErrorWorld':float(np.max(np.abs(srcpoint-canpoint))),'sourceDepthRayScalar':float(delta@ray),'sourceDepthPerpendicularResidual':float(np.linalg.norm(delta-ray*(delta@ray)))})
 maps[food]={'sourceMode':mode,'sourceTexture':{'path':str(src),'sha256':sha(src),'imageSize':S['size'],'actualUV':uv,'actualVertices':v,'actualPlane':a['food']['plane'],'actualFoodRoot':a['food']['root']},'canonicalTexture':{'path':str(canon.resolve()),'sha256':sha(canon),'imageSize':C['size']},'definition':'Threshold alpha >=128; visible width is occupied alpha bbox width. Actual bottom rim support is the center of the lowest opaque row span, at pixel centers. Preserve canonical full raster and full [0,1] UV with one uniform mapping, not the source padded quad corners.','threshold':128,'sourceMetrics':S,'canonicalMetrics':C,'sourceVisibleWidthWorldCells':visibleWorldWidth,'canonicalFullQuadWidthWorldCells':cw*k*1.25,'canonicalFullQuadHeightWorldCells':ch*k*1.25,'sourceSupportPlaneLocal':srcAnchor,'canonicalPixelScalePlaneLocal':k,'canonicalBottomOriginOffsetPlaneLocal':offset,'proposedFullUV':[[0,0],[1,0],[1,1],[0,1]],'proposedVerticesPlaneLocal':vertices,'sensitivity':sens,'sampleCount':len(proof),'sampleProofSHA256':digest(proof),'sourceDepthBaseline':{'scalarMin':min(s['sourceDepthRayScalar'] for s in proof),'scalarMax':max(s['sourceDepthRayScalar'] for s in proof),'maxPerpendicularResidual':max(s['sourceDepthPerpendicularResidual'] for s in proof)},'proofSamples':proof}
